import iconv from 'iconv-lite';
import { bookFromText } from './textUtils';
import { stripExtension } from './formats';
import type { Book, TxtEncoding } from './types';

export async function parseTxt(file: File, encoding: TxtEncoding = 'utf-8'): Promise<Book> {
  const buf = Buffer.from(await file.arrayBuffer());
  const text = iconv.decode(buf, encoding === 'gbk' ? 'gbk' : 'utf8');
  if (!text.trim()) {
    throw new Error('TXT 内容为空，或编码选择不正确');
  }
  return bookFromText(text, stripExtension(file.name));
}

