import './ui/app.css';
import './ui/sw-register';
import * as pdfjsLib from 'pdfjs-dist';
import pdfWorkerUrl from 'pdfjs-dist/build/pdf.worker.min.mjs?url';
import {
  detectFormat,
  FORMAT_LABELS,
  legalTargets,
  sanitizeName,
  stripExtension,
} from './core/formats';
import { convert, errorSummary } from './core/converter';
import { addHistory, clearHistory, loadHistory } from './core/history';
import { canShareFile, downloadFile, shareFile } from './core/output';
import type {
  BuiltFile,
  ConvertStatus,
  Format,
  HistoryEntry,
  TxtEncoding,
} from './core/types';

pdfjsLib.GlobalWorkerOptions.workerSrc = pdfWorkerUrl;

type View = 'pick' | 'options' | 'converting' | 'result';

interface State {
  view: View;
  file: File | null;
  source: Format | null;
  target: Format | null;
  outputName: string;
  txtEncoding: TxtEncoding;
  epubTitle: string;
  detecting: boolean;
  progress: number;
  progressLabel: string;
  abort: AbortController | null;
  result:
    | { status: ConvertStatus; built?: BuiltFile; filename?: string; error?: string }
    | null;
}

const state: State = {
  view: 'pick',
  file: null,
  source: null,
  target: null,
  outputName: '',
  txtEncoding: 'utf-8',
  epubTitle: '',
  detecting: false,
  progress: 0,
  progressLabel: '',
  abort: null,
  result: null,
};

const screenEl = document.getElementById('screen')!;
const fileInput = document.createElement('input');
fileInput.type = 'file';
fileInput.accept = '.txt,.docx,.epub,.pdf,text/plain,.pdf,.epub';
fileInput.style.display = 'none';
fileInput.addEventListener('change', () => {
  const f = fileInput.files?.[0];
  if (f) void pickFile(f);
  fileInput.value = '';
});
document.body.appendChild(fileInput);

const $ = (sel: string) => document.querySelector(sel);

function render(): void {
