    zone.style.background = '';
    const f = e.dataTransfer?.files?.[0];
    if (f) void pickFile(f);
  });
}

async function pickFile(file: File): Promise<void> {
  state.detecting = true;
  state.file = file;
  state.source = null;
  state.target = null;
  state.view = 'options';
  state.result = null;
  state.outputName = stripExtension(file.name);
  state.txtEncoding = 'utf-8';
  state.epubTitle = '';
  renderOptions();
  setPickSub('正在识别文件格式…');

  const fmt = await detectFormat(file);
  if (!fmt) {
    state.view = 'pick';
    render();
    toast('无法识别文件格式，请选择 txt / docx / epub / pdf 文件');
    return;
  }
  state.source = fmt;
  const targets = legalTargets(fmt);
  state.target = targets[0] ?? null;
  renderOptions();
}

function setPickSub(text: string): void {
  const el = screenEl.querySelector('#pickZone .pick-sub');
  if (el) el.textContent = text;
}

/* ---------------- 选项 ---------------- */

function formatSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / 1024 / 1024).toFixed(2)} MB`;
}

function renderOptions(): void {
  const { file, source, target, detecting } = state;
  const targets = source ? legalTargets(source) : [];

  const showTxtEncoding = source === 'txt' || target === 'txt';
  const encodingLabel =
    source === 'txt'
      ? 'TXT 编码（打开后乱码请改选 GBK）'
      : 'TXT 输出编码';
  const showEpubTitle = target === 'epub';

  screenEl.innerHTML = `
    <div class="steps">
      <span class="dot active"></span><span>选文件</span>
      <span class="dot ${file ? 'active' : ''}"></span><span>选格式</span>
      <span class="dot ${target ? 'active' : ''}"></span><span>转换</span>
