          ? `
      <div class="field">
        <label>${encodingLabel}</label>
        <div class="segmented" id="encSeg">
          <button data-enc="utf-8" class="${state.txtEncoding === 'utf-8' ? 'active' : ''}">UTF-8（默认）</button>
