/**
 * GBK 编码器：把字符串编码为 GBK 字节流。
 * ASCII 按单字节，其余字符查 GBK 双字节码表；查不到的字符用 '?' 替代。
 * 码表数据来源：WHATWG encoding index gbk 反查表（公开数据）。
 */

let table: Uint16Array | null = null;
let tableLoaded: Promise<Uint16Array> | null = null;

export async function loadGbkTable(): Promise<Uint16Array> {
  if (table) return table;
  if (!tableLoaded) {
    tableLoaded = import('../../public/data/gbk-encode.bin?url')
      .catch(() => import('./gbk-table-url'))
      .then(async (mod) => {
        const res = await fetch(mod.default);
        if (!res.ok) throw new Error('GBK 码表加载失败');
        return new Uint16Array(await res.arrayBuffer());
      });
  }
  return tableLoaded;
}

