mkdir -p /workspace/ebook-converter/public/data /workspace/ebook-converter/scripts && cat > /workspace/ebook-converter/scripts/build-gbk-table.mjs <<'EOF'
// 由 iconv-lite 的 GBK 反向表生成 Unicode codepoint -> GBK 双字节 码表
import iconv from 'iconv-lite';
import { writeFileSync, mkdirSync } from 'node:fs';

mkdirSync('public/data', { recursive: true });

// table[unicode] = gbk double-byte value (0 if none)
const table = new Uint16Array(0x10000);

// iconv-lite gbk 编码内部表：遍历所有可能双字节值并解码
for (let hi = 0x81; hi <= 0xfe; hi++) {
  for (let lo = 0x40; lo <= 0xfe; lo++) {
    if (lo === 0x7f) continue;
    const buf = Buffer.from([hi, lo]);
    const decoded = iconv.decode(buf, 'gbk');
    // 只接受解码为单个 BMP 字符的组合（拒绝未定义区域，解码会产生 U+FFFD 或双字符）
    if ([...decoded].length !== 1) continue;
    const cp = decoded.codePointAt(0);
    if (cp >= 0x80 && cp <= 0xffff && table[cp] === 0) {
      table[cp] = (hi << 8) | lo;
    }
  }
}

const bin = Buffer.from(table.buffer);
writeFileSync('public/data/gbk-encode.bin', bin);
console.log('entries:', [...table].filter(Boolean).length, 'bytes:', bin.length);

// 自检：编码「中文测试 abc」
const sample = '中文测试';
const bytes = [];
for (const ch of sample) {
  const cp = ch.codePointAt(0);
  const v = table[cp];
  bytes.push(v >> 8, v & 0xff);
}
const encoded = Buffer.from(bytes);
const back = iconv.decode(encoded, 'gbk');
console.log('roundtrip:', sample, '->', [...encoded].map(b=>b.toString(16)).join(' '), '->', back);
if (back !== sample) process.exit(1);
EOF
