import type { BuiltFile } from './types';

export function downloadFile(bytes: Uint8Array, filename: string, mime: string): void {
  const blob = new Blob([bytes as BlobPart], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 10_000);
}

export function canShareFile(): boolean {
  return typeof navigator.canShare === 'function' &&
    typeof navigator.share === 'function';
}

/** 调用系统分享（微信/QQ/蓝牙/保存到文件等由系统提供） */
export async function shareFile(
  bytes: Uint8Array,
  filename: string,
  mime: string,
): Promise<'shared' | 'cancelled' | 'unsupported'> {
  if (!canShareFile()) return 'unsupported';
  const file = new File([bytes as BlobPart], filename, { type: mime });
  if (!navigator.canShare({ files: [file] })) return 'unsupported';
  try {
    await navigator.share({ files: [file], title: filename });
    return 'shared';
  } catch (err) {
    if (err instanceof DOMException && err.name === 'AbortError') return 'cancelled';
    throw err;
  }
}

import iconv from 'iconv-lite';
import { bookFromText } from './textUtils';
import { stripExtension } from './formats';
import type { Book, TxtEncoding } from './types';

export async function parseTxt(file: File, encoding: TxtEncoding = 'utf-8'): Promise<Book> {
  const bytes = new Uint8Array(await file.arrayBuffer());
  const decoder = new TextDecoder(encoding === 'gbk' ? 'gbk' : 'utf-8', { fatal: false });
  const text = decoder.decode(bytes);
  if (!text.trim()) {
    throw new Error('TXT 内容为空，或编码选择不正确');
  }
  return bookFromText(text, stripExtension(file.name));
}

