import type { jsPDF } from 'jspdf';
import { FORMAT_MIMES } from './formats';
import { loadCjkFont, FONT_FAMILY, FONT_FILE } from './pdfFont';
import type { Book, BuiltFile, ConvertOptions } from './types';

// A4: 210×297mm
const PAGE_W = 210;
const PAGE_H = 297;
const MARGIN_X = 20;
const MARGIN_TOP = 22;
const MARGIN_BOTTOM = 22;
const CONTENT_W = PAGE_W - MARGIN_X * 2;
const FONT_SIZE = 12;
const TITLE_SIZE = 22;
const HEADING_SIZE = 16;
const LINE_GAP = 7;

export async function buildPdf(book: Book, opts: ConvertOptions): Promise<BuiltFile> {
  opts.onProgress?.(0.58, '正在加载中文字体');
  const fontBase64 = await loadCjkFont();
  opts.signal.throwIfAborted();

  const doc = new jsPDF({ unit: 'mm', format: 'a4' });
  doc.addFileToVFS(FONT_FILE, fontBase64);
  doc.addFont(FONT_FILE, FONT_FAMILY, 'normal');
  doc.setFont(FONT_FAMILY, 'normal');

  let y = MARGIN_TOP;
  let work = 0;
  const totalWork = estimateWork(book);

  // 封面
  doc.setFontSize(TITLE_SIZE);
  const titleLines = wrapText(doc, book.title || '未命名', CONTENT_W);
  y = PAGE_H / 2 - (titleLines.length * TITLE_SIZE) / 4;
  for (const line of titleLines) {
    doc.text(line, PAGE_W / 2, y, { align: 'center' });
    y += LINE_GAP + 3;
  }

  const ensureSpace = (needed: number) => {
    if (y + needed > PAGE_H - MARGIN_BOTTOM) {
      doc.addPage();
      y = MARGIN_TOP;
    }
  };

  for (const ch of book.chapters) {
    opts.signal.throwIfAborted();
    doc.addPage();
    y = MARGIN_TOP;
    doc.setFontSize(HEADING_SIZE);
    for (const hLine of wrapText(doc, ch.title, CONTENT_W)) {
      doc.text(hLine, MARGIN_X, y);
      y += LINE_GAP + 2;
    }
    y += 4;

    doc.setFontSize(FONT_SIZE);
    for (const para of ch.paragraphs) {
      const lines = wrapText(doc, '　　' + para, CONTENT_W);
      for (const line of lines) {
        ensureSpace(LINE_GAP);
        doc.text(line, MARGIN_X, y);
        y += LINE_GAP;
        work += 1;
      }
      y += 2; // 段间距
      if ((work & 31) === 0) {
        opts.onProgress?.(0.62 + 0.33 * Math.min(work / Math.max(totalWork, 1), 1), '正在排版 PDF');
      }
    }
    opts.onProgress?.(0.62 + 0.33 * Math.min(work / Math.max(totalWork, 1), 1), '正在排版 PDF');
  }

  opts.signal.throwIfAborted();
  opts.onProgress?.(0.96, '正在生成 PDF');
  const arrayBuffer = doc.output('arraybuffer');
  return {
    bytes: new Uint8Array(arrayBuffer),
    mime: FORMAT_MIMES.pdf,
    extension: 'pdf',
  };
}

function estimateWork(book: Book): number {
  let n = 0;
  for (const ch of book.chapters) {
    for (const p of ch.paragraphs) {
      // 粗略估算：每 45 个字符一行
      n += Math.ceil(p.length / 45);
    }
  }
  return Math.max(n, 1);
}

/** jsPDF 的 splitTextToSize 对 TTF 中文字体按字宽换行 */
function wrapText(doc: jsPDF, text: string, maxWidth: number): string[] {
  return doc.splitTextToSize(text, maxWidth) as unknown as string[];
}

