 * 输出编码由界面选项单独控制。
 */
export async function parseTxt(file: File): Promise<Book> {
  const bytes = new Uint8Array(await file.arrayBuffer());
  const text = decodeTxtBytes(bytes);
  if (!text.trim()) {
    throw new Error('TXT 内容为空，无法转换');
