/**
 * 懒加载内嵌中文字体（Droid Sans Fallback，Apache-2.0），
 * 仅在生成 PDF 时下载，Base64 缓存在内存中，供多个 jsPDF 实例使用。
 */

let cachedBase64: string | null = null;
let inflight: Promise<string> | null = null;

const FONT_URL = `${import.meta.env.BASE_URL}fonts/DroidSansFallback.ttf`;
export const FONT_FAMILY = 'DroidSansFallback';
export const FONT_FILE = 'DroidSansFallback.ttf';

export function loadCjkFont(): Promise<string> {
  if (cachedBase64) return Promise.resolve(cachedBase64);
  if (!inflight) {
    inflight = (async () => {
      const res = await fetch(FONT_URL);
      if (!res.ok) throw new Error(`中文字体加载失败（HTTP ${res.status}）`);
      const bytes = new Uint8Array(await res.arrayBuffer());
      const b64 = bytesToBase64(bytes);
      cachedBase64 = b64;
      return b64;
    })();
    inflight.catch(() => {
      inflight = null;
    });
  }
  return inflight;
}

/** 分块 Base64，避免 String.fromCharCode 超大参数爆栈 */
function bytesToBase64(bytes: Uint8Array): string {
  let binary = '';
  const CHUNK = 0x8000;
  for (let i = 0; i < bytes.length; i += CHUNK) {
    binary += String.fromCharCode(...bytes.subarray(i, i + CHUNK));
  }
  return btoa(binary);
}

/**
 * GBK 编码器：字符串 → GBK 字节流。
 * ASCII 单字节，其余字符查码表得到双字节；查不到的字符用 '?' 替代。
 * 码表以 Base64 文本存放（仅 170KB，且只在选择 GBK 输出时按需下载），
 * 解码为 Uint16Array，下标是 Unicode 码位，值是 GBK 双字节值。
 */

let inflight: Promise<Uint16Array> | null = null;

function loadTable(): Promise<Uint16Array> {
  if (!inflight) {
    inflight = (async () => {
      const url = `${import.meta.env.BASE_URL}data/gbk-encode.txt`;
      const res = await fetch(url);
      if (!res.ok) throw new Error('GBK 码表加载失败');
      const b64 = (await res.text()).trim();
      const bin = atob(b64);
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      // 用独立的 ArrayBuffer 按小端解析为 Uint16Array
      const ab = new ArrayBuffer(bytes.length);
      new Uint8Array(ab).set(bytes);
      return new Uint16Array(ab);
    })();
    inflight.catch(() => {
      inflight = null;
    });
  }
  return inflight;
}

export async function encodeGbk(text: string): Promise<Uint8Array> {
  const table = await loadTable();
  const out: number[] = [];
  for (const ch of text) {
    const code = ch.codePointAt(0)!;
    if (code < 0x80) {
      out.push(code);
    } else if (code <= 0xffff) {
      const gbk = table[code];
      if (gbk) {
        out.push(gbk >> 8, gbk & 0xff);
      } else {
        out.push(0x3f); // ?
      }
    } else {
      out.push(0x3f); // GBK 以外的扩展字符（emoji 等）
    }
  }
  return new Uint8Array(out);
}

