  await pickFile(page, 'demo.txt', SAMPLE);
  await page.waitForSelector('[data-target="epub"]');
  check('源格式自动识别为 TXT', (await page.locator('.file-badge').innerText()) === 'TXT');
  const targets = await page.locator('.format-chip').allInnerTexts();
