async function pickFile(file: File): Promise<void> {
  state.detecting = true;
  state.file = file;
  state.source = null;
  state.target = null;
  state.view = 'options';
  state.result = null;
  state.outputName = stripExtension(file.name);
  state.txtEncoding = 'utf-8';
  state.epubTitle = '';
  renderOptions();
  setPickSub('正在识别文件格式…');

  const fmt = await detectFormat(file);
  if (!fmt) {
    state.view = 'pick';
    render();
    toast('无法识别文件格式，请选择 txt / docx / epub / pdf 文件');
    return;
  }
  state.source = fmt;
  const targets = legalTargets(fmt);
  state.target = targets[0] ?? null;
  renderOptions();
}

function setPickSub(text: string): void {
  const el = screenEl.querySelector('#pickZone .pick-sub');
  if (el) el.textContent = text;

